pub fn analyze_program(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<ModuleId, &'static str> {
    if node.type_name != "program" {
        return Err("unexpected AST node");
    }
    match node.variant_name.as_str() {
        "" => analyze_program_alt_0(ctx, scope, node),
        _ => Err("unexpected AST variant"),
    }
}

fn analyze_program_alt_0(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<ModuleId, &'static str> {
    let children = |field_name: &str| {
        node.field_names
            .iter()
            .position(|field| field == field_name)
            .and_then(|index| node.elements.get(index))
            .filter(|value| value.kind == AstValueKind::List)
            .ok_or("missing child list")
    };
    let declarations = children("declarations")?;
    if declarations
        .elements
        .iter()
        .any(|value| !is_declaration_ast(value))
    {
        return Err("unexpected child list item");
    }
    let state = ();
    for item in declarations.elements.iter() {
        let _ = match analyze_declaration(&mut *ctx, scope, item) { Ok(value) => value, Err(failure_message) => ctx.record_error(failure_message, item.source_span) };
    }
    let result = ctx.create_module(scope);
    Ok(result)
}

pub fn analyze_declaration(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<(), &'static str> {
    if node.type_name == "varDeclaration" || (node.kind != AstValueKind::Node && is_var_declaration_ast(node)) {
        return analyze_declaration_alt_0(ctx, scope, node);
    }
    if node.type_name == "funDeclaration" || (node.kind != AstValueKind::Node && is_fun_declaration_ast(node)) {
        return analyze_declaration_alt_1(ctx, scope, node);
    }
    if node.type_name == "funDefinition" || (node.kind != AstValueKind::Node && is_fun_definition_ast(node)) {
        return analyze_declaration_alt_2(ctx, scope, node);
    }
    if node.type_name == "methodOutOf" || (node.kind != AstValueKind::Node && is_method_out_of_ast(node)) {
        return analyze_declaration_alt_3(ctx, scope, node);
    }
    if node.type_name == "constructorOutOf" || (node.kind != AstValueKind::Node && is_constructor_out_of_ast(node)) {
        return analyze_declaration_alt_4(ctx, scope, node);
    }
    if node.type_name == "destructorOutOf" || (node.kind != AstValueKind::Node && is_destructor_out_of_ast(node)) {
        return analyze_declaration_alt_5(ctx, scope, node);
    }
    if node.type_name == "structDeclaration" || (node.kind != AstValueKind::Node && is_struct_declaration_ast(node)) {
        return analyze_declaration_alt_6(ctx, scope, node);
    }
    if node.type_name == "classDeclaration" || (node.kind != AstValueKind::Node && is_class_declaration_ast(node)) {
        return analyze_declaration_alt_7(ctx, scope, node);
    }
    if node.type_name != "declaration" {
        return Err("unexpected AST node");
    }
    Err("unexpected AST variant")
}

fn analyze_declaration_alt_0(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<(), &'static str> {
    let value = node;
    let target = ctx.ordinary_target();
    let analyzed = analyze_var_declaration(&mut *ctx, scope, target, value)?;
    let result = analyzed;
    Ok(result)
}

