fn analyze_var_initialization_alt_0(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<(), &'static str> {
    let child = |field_name: &str| {
        node.field_names
            .iter()
            .position(|field| field == field_name)
            .and_then(|index| node.elements.get(index))
            .ok_or("missing child node")
    };
    let r#type = child("type")?;
    if !is_type_specifier_ast(r#type) {
        return Err("unexpected child AST node");
    }
    let name = child("name")?;
    if !is_declarator_ast(name) {
        return Err("unexpected child AST node");
    }
    let value = child("value")?;
    if !is_expression_ast(value) {
        return Err("unexpected child AST node");
    }
    let declared_type = analyze_type_specifier(&mut *ctx, scope, r#type)?;
    let identifier = analyze_declarator(&mut *ctx, name)?;
    let symbol =
        ctx.begin_initializer(scope, identifier.as_str(), declared_type, node.source_span)?;
    let initializer = match analyze_expression(&mut *ctx, scope, value) { Ok(value) => value, Err(failure_message) => ctx.recover_expression(failure_message, value.source_span) };
    let result = ctx.finish_initializer(scope, symbol, initializer, node.source_span)?;
    Ok(result)
}

