fn analyze_var_construction_alt_0(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<(), &'static str> {
    let child = |field_name: &str| {
        node.field_names
            .iter()
            .position(|field| field == field_name)
            .and_then(|index| node.elements.get(index))
            .ok_or("missing child node")
    };
    let r#type = child("type")?;
    if !is_type_specifier_ast(r#type) {
        return Err("unexpected child AST node");
    }
    let name = child("name")?;
    if !is_declarator_ast(name) {
        return Err("unexpected child AST node");
    }
    let arguments = node.field_names.iter()
        .position(|field| field == "arguments")
        .and_then(|index| node.elements.get(index))
        .filter(|value| value.kind == AstValueKind::Optional)
        .ok_or("missing optional child")?;
    let arguments = arguments.elements.first();
    if arguments.is_some_and(|value| !is_arg_list_ast(value)) {
        return Err("unexpected optional child");
    }
    let declared_type = analyze_type_specifier(&mut *ctx, scope, r#type)?;
    let identifier = analyze_declarator(&mut *ctx, name)?;
    let symbol =
        ctx.begin_construction(scope, identifier.as_str(), declared_type, node.source_span)?;
    let values = match arguments { Some(child) => analyze_arg_list(&mut *ctx, scope, child)?, None => Vec::<ExprId>::new() };
    let result = ctx.finish_construction(scope, symbol, &values, node.source_span)?;
    Ok(result)
}

