pub fn analyze_expression(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<ExprId, &'static str> {
    if node.type_name != "expression" && is_additive_expression_ast(node) {
        let normalized = AstValue {
            kind: AstValueKind::Node,
            source_span: node.source_span,
            recognized_span: node.recognized_span,
            type_name: "expression".to_owned(),
            variant_name: String::new(),
            token_kind: 0,
            token_text: String::new(),
            field_names: vec!["left".to_owned(), "comparison".to_owned()],
            elements: vec![node.clone(), AstValue { kind: AstValueKind::Optional, source_span: node.source_span, recognized_span: node.recognized_span, type_name: String::new(), variant_name: String::new(), token_kind: 0, token_text: String::new(), field_names: Vec::new(), elements: Vec::new() }],
        };
        return analyze_expression_alt_0(ctx, scope, &normalized);
    }
    if node.type_name != "expression" {
        return Err("unexpected AST node");
    }
    match node.variant_name.as_str() {
        "" => analyze_expression_alt_0(ctx, scope, node),
        _ => Err("unexpected AST variant"),
    }
}

fn analyze_expression_alt_0(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<ExprId, &'static str> {
    let child = |field_name: &str| {
        node.field_names
            .iter()
            .position(|field| field == field_name)
            .and_then(|index| node.elements.get(index))
            .ok_or("missing child node")
    };
    let left = child("left")?;
    if !is_additive_expression_ast(left) {
        return Err("unexpected child AST node");
    }
    let comparison = node.field_names.iter()
        .position(|field| field == "comparison")
        .and_then(|index| node.elements.get(index))
        .filter(|value| value.kind == AstValueKind::Optional)
        .ok_or("missing optional child")?;
    let comparison = comparison.elements.first();
    if comparison.is_some_and(|value| !is_comparison_tail_ast(value)) {
        return Err("unexpected optional child");
    }
    let lhs = match analyze_additive_expression(&mut *ctx, scope, left) { Ok(value) => value, Err(failure_message) => ctx.recover_expression(failure_message, left.source_span) };
    let result_value = match comparison { Some(child) => analyze_comparison_tail(&mut *ctx, scope, lhs, child)?, None => lhs };
    let result = result_value;
    Ok(result)
}

pub fn analyze_comparison_tail(
    ctx: &mut Context,
    scope: ScopeId,
    left: ExprId,
    node: &AstValue,
) -> Result<ExprId, &'static str> {
    if node.kind != AstValueKind::Record || node.type_name != "comparisonTail" {
        return Err("unexpected AST record");
    }
    analyze_comparison_tail_alt_0(ctx, scope, left, node)
}

fn analyze_comparison_tail_alt_0(
    ctx: &mut Context,
    scope: ScopeId,
    left: ExprId,
    node: &AstValue,
) -> Result<ExprId, &'static str> {
    let child = |field_name: &str| {
        node.field_names
            .iter()
            .position(|field| field == field_name)
            .and_then(|index| node.elements.get(index))
            .ok_or("missing child node")
    };
    let operator = child("operator")?;
    if !is_relop_ast(operator) {
        return Err("unexpected child AST node");
    }
    let right = child("right")?;
    if !is_additive_expression_ast(right) {
        return Err("unexpected child AST node");
    }
    let operation = analyze_relop(&mut *ctx, operator)?;
    let rhs = match analyze_additive_expression(&mut *ctx, scope, right) { Ok(value) => value, Err(failure_message) => ctx.recover_expression(failure_message, right.source_span) };
    let result = ctx.binary_expr(operation, left, rhs, node.source_span)?;
    Ok(result)
}

