pub fn analyze_factor(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<ExprId, &'static str> {
    if matches!(node.type_name.as_str(), "additiveExpression" | "expression" | "term") {
        return analyze_factor_alt_0(ctx, scope, node);
    }
    if node.type_name == "varUsage" {
        return analyze_factor_alt_1(ctx, scope, node);
    }
    if node.type_name == "call" {
        return analyze_factor_alt_2(ctx, scope, node);
    }
    if is_bool_literal_ast(node) {
        return analyze_factor_alt_7(ctx, scope, node);
    }
    if node.type_name != "factor" {
        return Err("unexpected AST node");
    }
    match node.variant_name.as_str() {
        "NumberFactor" => analyze_factor_alt_3(ctx, scope, node),
        "FloatFactor" => analyze_factor_alt_4(ctx, scope, node),
        "StringFactor" => analyze_factor_alt_5(ctx, scope, node),
        "CharFactor" => analyze_factor_alt_6(ctx, scope, node),
        "NullFactor" => analyze_factor_alt_8(ctx, scope, node),
        "NegatedFactor" => analyze_factor_alt_9(ctx, scope, node),
        _ => Err("unexpected AST variant"),
    }
}

