pub fn analyze_statement(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<OpId, &'static str> {
    if node.type_name == "whileStatement" || (node.kind != AstValueKind::Node && is_while_statement_ast(node)) {
        return analyze_statement_alt_0(ctx, scope, node);
    }
    if node.type_name == "forStatement" || (node.kind != AstValueKind::Node && is_for_statement_ast(node)) {
        return analyze_statement_alt_1(ctx, scope, node);
    }
    if node.type_name == "ifStatement" || (node.kind != AstValueKind::Node && is_if_statement_ast(node)) {
        return analyze_statement_alt_2(ctx, scope, node);
    }
    if node.type_name == "assignStatement" || (node.kind != AstValueKind::Node && is_assign_statement_ast(node)) {
        return analyze_statement_alt_3(ctx, scope, node);
    }
    if node.type_name == "call" || (node.kind != AstValueKind::Node && is_call_ast(node)) {
        return analyze_statement_alt_4(ctx, scope, node);
    }
    if node.type_name == "compoundStatement" || (node.kind != AstValueKind::Node && is_compound_statement_ast(node)) {
        return analyze_statement_alt_5(ctx, scope, node);
    }
    if node.type_name == "returnStatement" || (node.kind != AstValueKind::Node && is_return_statement_ast(node)) {
        return analyze_statement_alt_6(ctx, scope, node);
    }
    if node.type_name != "statement" {
        return Err("unexpected AST node");
    }
    Err("unexpected AST variant")
}

