pub fn analyze_return_statement(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<OpId, &'static str> {
    if node.type_name != "returnStatement" {
        return Err("unexpected AST node");
    }
    match node.variant_name.as_str() {
        "" => analyze_return_statement_alt_0(ctx, scope, node),
        _ => Err("unexpected AST variant"),
    }
}

fn analyze_return_statement_alt_0(
    ctx: &mut Context,
    scope: ScopeId,
    node: &AstValue,
) -> Result<OpId, &'static str> {
    let value = node.field_names.iter()
        .position(|field| field == "value")
        .and_then(|index| node.elements.get(index))
        .filter(|value| value.kind == AstValueKind::Optional)
        .ok_or("missing optional child")?;
    let value = value.elements.first();
    if value.is_some_and(|value| !is_expression_ast(value)) {
        return Err("unexpected optional child");
    }
    let returned = match value { Some(child) => Some(analyze_expression(&mut *ctx, scope, child)?), None => None };
    let result = crate::sema_lib_gen::function_return(&mut *ctx, returned, node.source_span)?;
    Ok(result)
}
